import { app, Menu } from 'electron';
import path from 'node:path';
import { writeFile, realpath } from 'node:fs/promises';
const directory = await realpath(process.env.HAIYUE_NOTIFICATION_TEST_ROOT);
process.env.HAIYUE_ELECTRON_USER_DATA = path.join(directory, 'product-user-data');
process.env.HAIYUE_STUDIO_DISABLE_NOTIFICATIONS = '1';
let sequence = 0;
app.once('browser-window-created', (_event, window) => {
  window.webContents.setBackgroundThrottling(false);
  const evaluate = code => window.webContents.executeJavaScript(code);
  const call = (channel, payload = {}) => evaluate(`window.haiyueStudio.invoke(${JSON.stringify({ schemaVersion: 1, id: `notification-test:${++sequence}`, correlationId: 'notification-test:product', channel, payload })}).then(r=>{if(!r.ok)throw Error(JSON.stringify(r.payload));return r.payload;})`);
  const wait = async predicate => { const deadline = Date.now() + 25_000; while (!await predicate()) { if (Date.now() > deadline) throw Error('notification product timeout'); await new Promise(resolve => setTimeout(resolve, 60)); } };
  const run = async () => {
    await wait(() => evaluate('document.body.dataset.status === "ready" && !!document.querySelector("#notification-settings input:not(:disabled)")'));
    if (Menu.getApplicationMenu() !== null || window.isMenuBarVisible()) throw Error('native menu must be removed');
    const toolbar = await evaluate(`['new-project','open-project','save-project','run-project'].map(id=>{const b=document.getElementById(id);return {id,icon:!!b.querySelector('svg'),text:b.textContent,label:b.getAttribute('aria-label'),title:b.getAttribute('title'),delay:b.closest('hy-tooltip')?.getAttribute('delay')};})`);
    if(toolbar.some(b=>!b.icon||b.text.trim()||!b.label||b.title||b.delay!=='1000'))throw Error(JSON.stringify(toolbar));
    window.webContents.sendInputEvent({type:'mouseMove',x:400,y:100});
    const point=await evaluate(`(()=>{document.activeElement?.blur();const b=document.getElementById('new-project'),r=b.getBoundingClientRect();window.toolbarHoverStarted=performance.now();return{x:Math.round(r.x+r.width/2),y:Math.round(r.y+r.height/2)}})()`);
    window.webContents.sendInputEvent({type:'mouseMove',...point});
    await new Promise(resolve=>setTimeout(resolve,600));
    const tooltipVisible=()=>evaluate('document.getElementById("new-project").closest("hy-tooltip").shadowRoot.querySelector("[role=tooltip]").classList.contains("visible")');
    if(await tooltipVisible())throw Error('tooltip appeared before one second');
    await wait(tooltipVisible);
    const hoverMs=await evaluate('performance.now()-window.toolbarHoverStarted');if(hoverMs<950)throw Error('tooltip delay too short');
    await writeFile(path.join(directory,'production-tooltip.png'),(await window.webContents.capturePage()).toPNG());
    window.webContents.sendInputEvent({type:'mouseMove',x:400,y:100});
    await wait(async()=>!await tooltipVisible());
    const initial = await call('notifications/get'); if (initial.preferences.sound !== true) throw Error('defaults not mounted');
    await evaluate('document.querySelector("#settings-button").click()');
    await wait(() => evaluate('document.querySelector("#settings-dialog").open'));
    await evaluate(`(()=>{const first=document.getElementById('settings-tabs').shadowRoot.querySelector('[role=tab]');first.focus();first.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true}));})()`);
    await wait(() => evaluate('document.getElementById("settings-tabs").value === "models"'));
    if(!await evaluate('document.getElementById("settings-models").getBoundingClientRect().width>0 && document.getElementById("settings-notifications").getBoundingClientRect().width===0'))throw Error('settings tabs must show only their category');
    await evaluate('new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))');
    await writeFile(path.join(directory,'production-models.png'),(await window.webContents.capturePage()).toPNG());
    await evaluate('document.getElementById("settings-tabs").value="agent"');
    await wait(() => evaluate('!!document.querySelector("select[aria-label=审批方式]")'));
    const approvalInitial = await call('conversation/replay');
    if (approvalInitial.approvalMode !== 'auto-review') throw Error('automatic project approval default missing');
    await evaluate('const select = document.querySelector("select[aria-label=审批方式]"); select.value = "ask"; select.dispatchEvent(new Event("change", {bubbles:true}))');
    await wait(async () => (await call('conversation/replay')).approvalMode === 'ask');
    await evaluate('document.getElementById("settings-tabs").value="notifications"');
    await wait(() => evaluate('document.querySelector("#settings-dialog").shadowRoot.querySelector("dialog").open && document.querySelector("[data-notification=sound]").getBoundingClientRect().width > 0'));
    await evaluate('document.querySelector("[data-notification=sound]").click()');
    await wait(async () => (await call('notifications/get')).preferences.sound === false);
    await evaluate('document.getElementById("settings-tabs").value="tools"');
    await wait(() => evaluate('!!document.querySelector("#query-settings input:not(:disabled)")'));
    const queryInitial = await call('queries/get');
    if (queryInitial.limits['engine.docs.search'] !== 12) throw Error('query defaults missing');
    await evaluate('document.querySelector("#query-settings input").value = "30"');
    await evaluate('document.querySelector("#query-settings button").click()');
    await wait(async () => (await call('queries/get')).limits['engine.docs.search'] === 30);
    const target = await call('notifications/target'); if (target.target !== null) throw Error('unexpected navigation target');
    await evaluate('new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)))');
    await writeFile(path.join(directory, 'production-settings.png'), (await window.webContents.capturePage()).toPNG());
    const loaded = new Promise(resolve => window.webContents.once('did-finish-load', resolve)); window.reload(); await loaded;
    await wait(() => evaluate('document.body.dataset.status === "ready" && !!document.querySelector("#notification-settings input:not(:disabled)")'));
    if (await evaluate('document.querySelector("[data-notification=sound]").checked')) throw Error('renderer reload lost mute preference');
    await wait(() => evaluate('document.querySelector("#query-settings input:not(:disabled)")?.value === "30"'));
    const queryFinal = await call('queries/get');
    await wait(() => evaluate('document.querySelector("select[aria-label=审批方式]")?.value === "ask"'));
    const approvalFinal = await call('conversation/replay');
    window.webContents.sendInputEvent({type:'keyDown',keyCode:'F12'});
    window.webContents.sendInputEvent({type:'keyUp',keyCode:'F12'});
    await wait(()=>window.webContents.isDevToolsOpened());
    window.webContents.closeDevTools();
    await wait(()=>!window.webContents.isDevToolsOpened());
    const final = await call('notifications/get'); await writeFile(path.join(directory, 'production.json'), JSON.stringify({ initial, final, queryInitial, queryFinal, approvalInitial:approvalInitial.approvalMode, approvalFinal:approvalFinal.approvalMode, toolbar, hoverMs,settingsTabs:5,nativeMenuRemoved:true,nativeShortcutsVerified:true,reloaded: true, typedPreload: true, nativeDeliveryDisabledForTest: true }, null, 2));
    console.log('[notification-product] passed'); app.quit();
  };
  window.webContents.once('did-finish-load', () => { run().catch(cause => { console.error(cause); app.exit(1); }); });
});
await import('../../dist/main.js');
